INSERT INTO changelog (title, body, created_at) VALUES ('Конструктор кампаній Meta', 'Клієнт → Meta Ads → «Кампанії» (або кнопка «+ Нова кампанія» зверху). Кампанія → групи оголошень → оголошення, як у Ads Manager: кожне поле з кнопкою «Копіювати» і лічильником символів (основний текст 125 до «Ще», заголовок 40, опис 30). Нова кампанія: назва, ціль, бюджет, ідея — і Джері сам збирає групи, таргетинг і 2–4 оголошення з текстами (з урахуванням історії клієнта, брендбуку, найдешевших оголошень і уроків). В оголошенні: завантаж фото/відео або візьми креатив з робочого оголошення Meta, «Тексти від Джері» — бачить картинку і пише 3 основні тексти, 5 заголовків, 3 описи (кнопка «Взяти» ставить варіант основним), «Промпт для Claude» — намалювати креатив (код CR-N). Прев''ю як у стрічці Facebook. Код AD-N у назві оголошення в Meta звʼязує з живими цифрами (витрати, ліди, ціна ліда проти цілі). «Перевірка перед запуском» — що не заповнено і де бюджет замалий. «Що вийшло» 👍/👎 + журнал (зміни, бюджет, уроки) — цифри дописуються самі, уроки Джері враховує в наступних кампаніях. Окрема вкладка «Креативи» в картці клієнта прибрана — креатив тепер частина оголошення. Дублювання кампанії, групи (напр. інше місто) й оголошення. Джері: інструмент ad_campaign.', datetime('now'));
